    +'<div id="peAutoBanner" style="flex:0 0 auto;display:none;margin:0 0 10px;padding:8px 12px;border:1px solid #cfe0d6;border-radius:11px;background:#eef7f1;color:#1f5e34;font-size:12.5px"></div>'
