  if(num(sc2.wartet_pruefung)>0) aufg.push({ico:'📷',txt:num(sc2.wartet_pruefung)+' Scan(s) warten auf deine Prüfung',sub:'Scan-Eingang in der Erfassung',oc:"scanEingangOeffnen()"});
