      +'<button onclick="offLookup()" style="padding:10px 12px;border:1px solid var(--k-e7e0d4);border-radius:10px;background:var(--k-fbf8f2);color:var(--k-2e7d32);font-size:12.5px;white-space:nowrap;cursor:pointer">🔎 Open Food Facts</button>'
    +'</div>'
    +'<div id="tbmOffMsg" style="font-size:11.5px;color:var(--k-6b6256);margin-bottom:6px"></div>'
