/* Markierung ist PERSISTENT (Produkte.Markiert, RPC cb_produkt_markieren) – sie ueberlebt
   Neuladen und Session. Kein fluechtiges Set mehr (Ralph 20.07.). */
async function verifToggle(id){
  var rows=window._verifRows||[]; var r=rows.find(function(x){return String(x.id)===String(id);}); if(!r) return;
  var neu=!r.markiert;
  try{ var res=await client.rpc("cb_produkt_markieren",{p_id:id,p_an:neu}); if(res.error) throw res.error; r.markiert=neu; }
  catch(e){ alert("Markierung konnte nicht gespeichert werden: "+(e.message||e)); return; }
  verifRender();
}
/* Vom Editor aus setzen (kein Re-Render der Liste noetig, nur den Zeilen-Status mitfuehren). */
async function fgEditMark(id, an){
  try{ var res=await client.rpc("cb_produkt_markieren",{p_id:id,p_an:!!an}); if(res.error) throw res.error;
    var r=(window._verifRows||[]).find(function(x){return String(x.id)===String(id);}); if(r) r.markiert=!!an;
  }catch(e){ alert("Markierung konnte nicht gespeichert werden: "+(e.message||e)); }
}
function verifClear(){
  var marked=(window._verifRows||[]).filter(function(x){return x.markiert;});
  if(!marked.length) return;
  if(!confirm("Alle "+marked.length+" Markierungen entfernen?")) return;
  Promise.all(marked.map(function(r){ return client.rpc("cb_produkt_markieren",{p_id:r.id,p_an:false}).then(function(){ r.markiert=false; }); })).then(verifRender).catch(function(e){ alert("Fehler: "+(e.message||e)); });
}
function verifRender(){
  const el=document.getElementById("fgZuverif"); if(!el) return;
  const rows=window._verifRows||[];
  const markN=rows.filter(function(r){return r.markiert;}).length;
  if(!rows.length){ el.innerHTML='<span style="color:var(--muted)">Nichts offen – alle aktiven Produkte sind verifiziert. 🎉</span>'; return; }
  const q=((document.getElementById("verifFilter")||{}).value||"").trim().toLowerCase();
  const nur=!!((document.getElementById("verifNur")||{}).checked);
  const grp={}; rows.forEach(function(r){ (grp[r.grund]=grp[r.grund]||[]).push(r); });
  const list=rows.filter(function(p){
    if(nur && !p.markiert) return false;
    if(!q) return true;
    return (String(p.name||"")+" "+String(p.marke||"")+" "+String(p.id||"")+" "+String(p.ean||"")+" "+String(p.kategorie||"")+" "+String(p.grund||"")).toLowerCase().indexOf(q)>=0;
  });
  var toolbar='<div style="position:sticky;top:0;background:var(--bg);padding:2px 0 8px;z-index:5">'
    +'<div style="font-size:12px;color:var(--muted);margin-bottom:6px"><b>'+rows.length+'</b> offen'
      +Object.keys(grp).map(function(g){ return ' · '+esc(g)+': '+grp[g].length; }).join('')+'</div>'
    +'<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">'
      +'<input id="verifFilter" oninput="verifRender()" value="'+esc(q)+'" placeholder="Filtern: Name, Marke, EAN, Grund…" style="flex:1;min-width:180px;padding:8px;border:1px solid var(--line);border-radius:8px;background:var(--card);color:var(--ink);font-size:13px">'
      +'<label style="display:flex;align-items:center;gap:5px;font-size:12.5px;color:var(--muted);white-space:nowrap;cursor:pointer"><input type="checkbox" id="verifNur" '+(nur?'checked':'')+' onchange="verifRender()" style="width:15px;height:15px">nur markierte</label>'
    +'</div>'
    +'<div style="display:flex;gap:10px;align-items:center;margin-top:6px;font-size:12.5px;flex-wrap:wrap">'
      +'<span style="color:'+(markN?'var(--k-166534)':'var(--muted)')+';font-weight:600">'+markN+' markiert <span style="font-weight:400;color:var(--muted)">(bleibt gespeichert)</span></span>'
      +(markN?'<button onclick="verifClear()" style="padding:5px 10px;border:1px solid var(--line);border-radius:8px;background:var(--card);color:var(--ink);cursor:pointer;font-size:12px">Alle Markierungen entfernen</button>':'')
      +'<span style="color:var(--muted);margin-left:auto">'+list.length+' angezeigt</span>'
    +'</div></div>';
  if(!list.length){ el.innerHTML=toolbar+'<div style="color:var(--muted);font-size:13px;margin-top:12px">Kein Treffer.</div>'; var f0=document.getElementById("verifFilter"); if(f0){ f0.focus(); f0.setSelectionRange(f0.value.length,f0.value.length);} return; }
  el.innerHTML=toolbar+list.map(function(p){ var on=!!p.markiert;
    return '<div style="background:var(--card);border:1px solid '+(on?'var(--k-16a34a)':'var(--line)')+';border-radius:12px;padding:11px;margin-bottom:7px;display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap">'
      +'<label style="display:flex;align-items:center;gap:10px;min-width:0;flex:1 1 260px;cursor:pointer"><input type="checkbox" '+(on?"checked":"")+' onclick="verifToggle(\''+p.id+'\')" style="width:17px;height:17px;flex:0 0 auto;accent-color:var(--k-16a34a)">'
      +'<span style="min-width:0"><b>'+esc(p.name||"?")+'</b> <span style="color:var(--muted)">· '+esc(p.marke||"")+'</span>'
      +'<div style="font-size:12px;color:var(--muted)">'+esc(p.id)+' · '+esc(p.kategorie||"")+' · '+esc(p.ean||"")+(p.erfasst?' · 🕒 '+esc(p.erfasst):'')+' · <span style="color:var(--k-b45309)">'+esc(p.grund||"")+'</span></div></span></label>'
      +'<div style="display:flex;gap:8px;flex:0 0 auto;align-items:center"><a href="https://www.google.com/search?q='+encodeURIComponent((p.name||"")+" "+(p.marke||"")+" Zutaten Nährwerte")+'" target="_blank" rel="noopener" style="font-size:12px;color:var(--k-0ea5e9)">🔎 suchen ↗</a>'
      +'<button onclick="openFgEditor(\''+p.id+'\')" style="padding:8px 12px;border:1px solid var(--k-0ea5e9);border-radius:8px;background:var(--card);color:var(--k-0369a1);cursor:pointer;font-size:13px">✏️ Bearbeiten</button></div>'
      +'</div>'; }).join("");
  var fi=document.getElementById("verifFilter"); if(fi && q){ fi.focus(); fi.setSelectionRange(fi.value.length,fi.value.length); }
}
if(typeof window!=='undefined'){ window.loadZuVerif=loadZuVerif; window.verifRender=verifRender; window.verifToggle=verifToggle; window.verifClear=verifClear; }
async function loadRezepteFree(){
  const box=document.getElementById("fgRezepteFree"); if(!box) return;
  try{
    const {data,error}=await client.rpc("cb_admin_rezepte_free");
    if(error){ box.innerHTML='<span style="color:var(--muted)">—</span>'; return; }
    window._rezFree=data||[];
    renderRezepteFree();
  }catch(e){ box.innerHTML='<span style="color:var(--muted)">—</span>'; }
}
function renderRezepteFree(){
  const box=document.getElementById("fgRezepteFree"); if(!box) return;
  const rows=window._rezFree||[];
  const q=_norm((document.getElementById("fgRezSuche")||{}).value||"");
  const list=q? rows.filter(r=>_norm(r.name||"").includes(q)) : rows;
  const freiN=rows.filter(r=>r.frei).length;
  if(!list.length){ box.innerHTML='<span style="color:var(--muted)">Keine Rezepte.</span>'; return; }
  box.innerHTML='<div style="font-size:12px;color:var(--muted);margin-bottom:6px">'+freiN+' von '+rows.length+' Rezepten frei</div>'
    + list.map(r=>'<label style="display:flex;align-items:center;gap:10px;background:var(--card);border:1px solid var(--line);border-radius:10px;padding:9px 11px;margin-bottom:6px;cursor:pointer">'
      +'<input type="checkbox" '+(r.frei?'checked':'')+' onchange="rezFreeToggle(\''+r.rezept_id+'\',this.checked)" style="width:18px;height:18px;cursor:pointer">'
      +'<span style="flex:1;min-width:0"><span style="font-weight:600">'+esc(r.name||"?")+'</span>'
      +'<span style="font-size:12px;color:var(--muted)"> · '+esc(r.rezept_id)+' · '+esc(r.status||"")+(r.sichtbarkeit&&r.sichtbarkeit!=="oeffentlich"?(" · "+esc(r.sichtbarkeit)):"")+'</span></span>'
      +(r.frei?'<span style="font-size:11px;font-weight:700;color:var(--k-16a34a)">FREE</span>':'<span style="font-size:11px;color:var(--muted)">🔒 Premium</span>')
      +'</label>').join("");
}
async function rezFreeToggle(id, frei){
  const {error}=await client.rpc("cb_rezept_free_setzen",{p_rezept:id,p_frei:frei});
  if(error){ alert("Fehler: "+error.message); return; }
  const r=(window._rezFree||[]).find(x=>x.rezept_id===id); if(r) r.frei=frei;
  renderRezepteFree();
}
/* ---- Admin: Bundles (AD-3) ---- */
async function loadBundles(){
  const box=document.getElementById("fgBundles"); if(!box) return;
  try{ const {data}=await client.rpc("cb_admin_bundles"); window._bundles=data||[]; renderBundles(); }
  catch(e){ box.innerHTML='<span style="color:var(--muted)">—</span>'; }
}
function renderBundles(){
  const box=document.getElementById("fgBundles"); if(!box) return;
  const list=window._bundles||[];
  box.innerHTML = list.length ? list.map(b=>'<div style="background:var(--card);border:1px solid var(--line);border-radius:10px;padding:10px 12px;margin-bottom:8px">'
    +'<div style="display:flex;justify-content:space-between;align-items:center;gap:8px"><b>'+esc(b.name)+'</b>'
    +'<span style="display:flex;gap:6px"><button onclick="bundleEdit(\''+b.bundle_id+'\')" style="padding:5px 9px;border:1px solid var(--line);border-radius:8px;background:var(--card);color:var(--ink);cursor:pointer;font-size:12px">Bearbeiten</button>'
    +'<button onclick="bundleDel(\''+b.bundle_id+'\',\''+esc(b.name).replace(/\x27/g,"")+'\')" style="padding:5px 9px;border:1px solid var(--k-fca5a5);border-radius:8px;background:var(--card);color:var(--k-dc2626);cursor:pointer;font-size:12px">Löschen</button></span></div>'
    +(b.ziel?'<div style="font-size:11px;color:var(--muted)">Ziel: '+esc(b.ziel)+'</div>':'')
    +'<div style="margin-top:6px">'+((b.produkte||[]).length?(b.produkte||[]).map(p=>prodRef(p.produkt_id,{name:p.name,marke:p.marke})).join(""):'<i style="color:var(--muted)">keine Produkte</i>')+'</div></div>').join("")
    : '<span style="color:var(--muted)">Noch keine Bundles.</span>';
}
function bundleNeu(){ window._bundleEdit={id:'',name:'',ziel:'',produkte:[]}; bundleEditorRender(); }
function bundleEdit(id){ const b=(window._bundles||[]).find(x=>x.bundle_id===id); if(!b) return; window._bundleEdit={id:b.bundle_id,name:b.name||'',ziel:b.ziel||'',produkte:(b.produkte||[]).map(p=>({id:p.produkt_id,name:p.name,marke:p.marke}))}; bundleEditorRender(); }
function bundleEditorRender(){
  const e=window._bundleEdit, box=document.getElementById("fgBundles"); if(!box) return;
  box.innerHTML='<div style="background:var(--card);border:1px solid var(--green);border-radius:12px;padding:12px">'
    +'<div style="font-weight:600;margin-bottom:8px">'+(e.id?'Bundle bearbeiten':'Neues Bundle')+'</div>'
    +'<input id="bnName" value="'+esc(e.name)+'" placeholder="Bundle-Name" style="width:100%;padding:9px;border:1px solid var(--line);border-radius:8px;background:var(--card);color:var(--ink);margin-bottom:6px">'
    +'<input id="bnZiel" value="'+esc(e.ziel)+'" placeholder="Ziel (optional, z. B. Frühstück / High Protein)" style="width:100%;padding:9px;border:1px solid var(--line);border-radius:8px;background:var(--card);color:var(--ink);margin-bottom:8px">'
    +'<div style="font-size:12px;color:var(--muted);margin-bottom:4px">Produkte im Bundle:</div><div id="bnChips" style="margin-bottom:6px"></div>'
    +'<input id="bnSuche" oninput="bundleSuche(this.value)" placeholder="Produkt suchen &amp; hinzufügen…" style="width:100%;padding:9px;border:1px solid var(--line);border-radius:8px;background:var(--card);color:var(--ink)">'
    +'<div id="bnSucheRes" style="margin:4px 0"></div>'
    +'<div style="margin-top:8px;display:flex;gap:8px"><button onclick="bundleSave()" style="padding:9px 14px;border:0;border-radius:8px;background:var(--green);color:var(--auf-gruen);font-weight:600;cursor:pointer">Speichern</button><button onclick="loadBundles()" style="padding:9px 14px;border:1px solid var(--line);border-radius:8px;background:var(--card);color:var(--ink);cursor:pointer">Abbrechen</button></div>'
    +'<div id="bnMsg" style="font-size:12px;margin-top:6px"></div></div>';
  bundleChips();
}
function bundleChips(){ const el=document.getElementById("bnChips"); if(!el) return; const ps=window._bundleEdit.produkte||[];
  el.innerHTML = ps.length? ps.map((p,i)=>'<span style="display:inline-flex;align-items:center;gap:5px;background:var(--greenlt);color:var(--greendk);border-radius:999px;padding:4px 10px;margin:2px;font-size:12px">'+esc(p.name||p.id)+' <span onclick="bundleRem('+i+')" style="cursor:pointer;font-weight:700">✕</span></span>').join("") : '<span style="color:var(--muted);font-size:12px">noch keine</span>'; }
function bundleRem(i){ window._bundleEdit.produkte.splice(i,1); bundleChips(); }
function bundleSuche(q){ const box=document.getElementById("bnSucheRes"); if(!box) return; q=(q||"").trim(); if(!q){ box.innerHTML=""; return; }
  const nq=_norm(q); const list=(ALL||[]).filter(p=>_prodMatch(p,nq))
                      .sort((a,b)=>(_relevanz(b,nq)-_relevanz(a,nq))||((b.clean_score??-1)-(a.clean_score??-1)))
                      .slice(0,6);
  box.innerHTML=list.map(p=>'<button onclick="bundleAdd(\''+p.id+'\')" style="display:block;width:100%;text-align:left;padding:7px 9px;border:1px solid var(--line);border-radius:8px;background:var(--card);color:var(--ink);margin-bottom:4px;cursor:pointer;font-size:13px">'+esc(p.name)+' <span style="color:var(--muted);font-size:11px">'+esc(mkLabel(p.marke)||"")+'</span></button>').join(""); }
function bundleAdd(id){ const p=(ALL||[]).find(x=>x.id===id); if(!p) return; if(!(window._bundleEdit.produkte||[]).some(x=>x.id===id)) window._bundleEdit.produkte.push({id:p.id,name:p.name,marke:p.marke}); bundleChips(); const s=document.getElementById("bnSuche"); if(s) s.value=""; const r=document.getElementById("bnSucheRes"); if(r) r.innerHTML=""; }
async function bundleSave(){ const e=window._bundleEdit, msg=document.getElementById("bnMsg");
  const name=(document.getElementById("bnName").value||"").trim(), ziel=(document.getElementById("bnZiel").value||"").trim();
  if(!name){ if(msg){msg.style.color="var(--k-dc2626)";msg.textContent="Name fehlt.";} return; }
  const ids=(e.produkte||[]).map(p=>p.id);
  const {error}=await client.rpc("cb_admin_bundle_speichern",{p_id:e.id||"",p_name:name,p_ziel:ziel,p_produkte:ids,p_status:"Aktiv"});
  if(error){ if(msg){msg.style.color="var(--k-dc2626)";msg.textContent="Fehler: "+error.message;} return; }
  loadBundles();
}
async function bundleDel(id,name){ if(!confirm('Bundle „'+name+'" löschen?')) return; const {error}=await client.rpc("cb_admin_bundle_del",{p_id:id}); if(error){ alert("Fehler: "+error.message); return; } loadBundles(); }
