const FN_URL = SUPABASE_URL + "/functions/v1/produkt-vorschlagen";
let _scanning = false, _lastCode = null, _lastCount = 0, _scanCb = null, _teardown = null, _scanLauf = 0;
function setVorMsg(t,color){ const e=document.getElementById("vorMsg"); if(!e)return; e.style.color=color||"var(--k-374151)"; e.innerHTML=t; }
async function sendVorschlag(){
  const v=(document.getElementById("vorInput").value||"").trim();
  if(!v){ setVorMsg("Bitte einen Link oder Barcode eingeben.","var(--k-dc2626)"); return; }
  setVorMsg("⏳ Hole Daten aus Open Food Facts…");
  const isUrl=/^https?:\/\//i.test(v);
  try{
    const r=await fetch(FN_URL,{ method:"POST",
      headers:{ "Content-Type":"application/json","Authorization":"Bearer "+SUPABASE_KEY,"apikey":SUPABASE_KEY },
      body: JSON.stringify(isUrl?{url:v}:{ean:v}) });
    const j=await r.json();
    if(j.ok){ setVorMsg("✅ Als <b>Entwurf</b> angelegt – wird vor Veröffentlichung geprüft. Danke!","var(--k-16a34a)"); document.getElementById("vorInput").value=""; }
    else { setVorMsg("⚠️ "+(j.message||j.error||"Konnte nicht erfasst werden."),"var(--k-b45309)"); }
  }catch(e){ setVorMsg("Fehler: "+e.message,"var(--k-dc2626)"); }
}
/* ---- Etikett-Foto: verkleinern -> base64 -> Warteschlange (Kamera ODER Datei) ---- */
function _compressSrc(src, maxPx, q){
  maxPx=maxPx||1280; q=q||0.8;
  return new Promise((resolve,reject)=>{
    const img=new Image();
    img.onload=()=>{ let w=img.naturalWidth, h=img.naturalHeight; const s=Math.min(1, maxPx/Math.max(w,h));
      w=Math.round(w*s); h=Math.round(h*s);
      const c=document.createElement("canvas"); c.width=w; c.height=h;
      c.getContext("2d").drawImage(img,0,0,w,h);
      resolve(c.toDataURL("image/jpeg",q)); };
    img.onerror=()=>reject(new Error("Bild konnte nicht gelesen werden")); img.src=src;
  });
}
async function _submitFoto(src, produktId, ean){
  const d=await _compressSrc(src);
  const {data,error}=await client.rpc("cb_foto_vormerken",{p_base64:d, p_produkt_id:produktId||null, p_ean:ean||null, p_quelle:"Web-Foto"});
  if(error) throw error; return data;
}
async function fotoFromFile(file, produktId, ean){
  const u=URL.createObjectURL(file);
  try{ return await _submitFoto(u, produktId, ean); } finally{ URL.revokeObjectURL(u); }
}
/* Live-Kamera (Webcam am PC, Rückkamera am Handy) -> dataURL */
function camCapture(){
  return new Promise((resolve)=>{
    let stream=null;
    const ov=document.createElement("div");
    ov.style.cssText="position:fixed;inset:0;z-index:9999;background:var(--k-000000);display:flex;flex-direction:column;align-items:center;justify-content:center";
    ov.innerHTML='<video autoplay playsinline style="max-width:100%;max-height:78vh"></video>'
      +'<div style="display:flex;gap:14px;margin-top:14px">'
      +'<button id="camShot" style="padding:12px 22px;border:0;border-radius:10px;background:var(--k-16a34a);color:var(--k-ffffff);font-size:16px;cursor:pointer">📸 Auslösen</button>'
      +'<button id="camX" style="padding:12px 18px;border:0;border-radius:10px;background:var(--card);color:var(--k-111111);font-size:16px;cursor:pointer">Abbrechen</button></div>';
    document.body.appendChild(ov);
    const video=ov.querySelector("video");
    const stop=()=>{ if(stream) stream.getTracks().forEach(t=>t.stop()); ov.remove(); };
    ov.querySelector("#camX").onclick=()=>{ stop(); resolve(null); };
    ov.querySelector("#camShot").onclick=()=>{
      try{ const c=document.createElement("canvas"); c.width=video.videoWidth||1280; c.height=video.videoHeight||720;
        c.getContext("2d").drawImage(video,0,0,c.width,c.height); const d=c.toDataURL("image/jpeg",0.85); stop(); resolve(d);
      }catch(e){ stop(); resolve(null); } };
    navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:"environment"}},audio:false})
      .then(s=>{ stream=s; video.srcObject=s; })
      .catch(e=>{ stop(); alert("Kamera nicht verfügbar: "+e.message+"\nNutze stattdessen „Datei“."); resolve(null); });
  });
}
async function fotoFromCam(produktId, ean){ const d=await camCapture(); if(!d) return null; return await _submitFoto(d, produktId, ean); }
/* ---- Mehrbild-Erfassung: bis zu 3 Etikettfotos sammeln, dann zusammen senden ---- */
const VOR_SLOTS=[["front","Vorderseite"],["zutaten","Zutaten"],["naehrwerte","Nährwerte"]];
